import { test, expect } from '@playwright/test';
import { decodeLiveData, visibleDepartures } from '../src/liveData';
import executed from './fixtures/departures-rpc/executed.json' with { type: 'json' };

// Generated by the pinned, network-isolated Postgres runner using the active
// captured RPC definition and synthetic rows. Never a claim of real cancellation.
test('actual SQL enums survive gateway, decoder and freshness classification', () => {
  const data = decodeLiveData(executed.gateway);
  const states = Object.fromEntries(visibleDepartures(data, Date.parse(executed.now)).map(d => [d.tripId, d.status]));
  expect(states).toEqual({ 'cancel-fresh': 'cancelled', 'cancel-stale': 'cancellation_unconfirmed', 'cancel-missing': 'cancellation_unconfirmed', 'skip-fresh': 'skipped', 'skip-stale': 'skipping_unconfirmed', 'no-data': 'no_data', 'no-realtime-stale': 'no_data', scheduled: 'scheduled', 'prediction-fresh': 'predicted', 'prediction-stale': 'scheduled' });
  expect(executed.sqlEnums['cancel-fresh']).toBe('canceled');
  const unsupported = structuredClone(executed.gateway); unsupported.departures[0]!.status = 'unexpected';
  expect(() => decodeLiveData(unsupported)).toThrow();
  const incorrect = structuredClone(executed.gateway); const skipped = incorrect.departures.find(d => d.status === 'skipped')!; skipped.expectedAt = executed.now;
  expect(() => decodeLiveData(incorrect)).toThrow();
  const duplicate = structuredClone(executed.gateway); duplicate.departures.push(duplicate.departures[0]!);
  expect(() => decodeLiveData(duplicate)).toThrow('Duplicate departure identity');
  for (const id of ['', 'arbitrary', 'departure:' + 'g'.repeat(64)]) {
    const invalid = structuredClone(executed.gateway); invalid.departures[0]!.id = id;
    expect(() => decodeLiveData(invalid)).toThrow('Invalid departure identity');
  }
});

test('SQL-backed departures render confirmed, unconfirmed, no-data and timed predictions distinctly', async ({ page }) => {
  await page.clock.install({ time: Date.parse(executed.now) });
  await page.clock.pauseAt(new Date(Date.parse(executed.now) + 1000));
  await page.route('**/api/live', route => route.fulfill({ json: executed.gateway }));
  await page.route('https://tile.openstreetmap.org/**', route => route.abort());
  await page.goto('/#/live');
  await page.getByText('Next departures · Ballina', { exact: true }).click();
  const row = (trip: string) => page.locator(`.departure-row[data-trip-id="${trip}"]`);
  await expect(row('cancel-fresh')).toContainText('Cancelled');
  await expect(row('cancel-stale')).toContainText('Cancellation unconfirmed');
  await expect(row('skip-fresh')).toContainText('Stop skipped · do not board here');
  await expect(row('skip-stale')).toContainText('Stop skip unconfirmed');
  await expect(row('no-data')).toContainText('Scheduled · no realtime data');
  await expect(row('prediction-fresh')).toContainText('Prediction');
  await expect(row('prediction-stale')).toContainText('Scheduled · prediction expired');
  await expect(row('cancel-missing')).toContainText('Cancellation unconfirmed');
  await expect(row('no-realtime-stale')).toContainText('Scheduled · no realtime data');
  await expect(page.locator('.departure-row')).toHaveCount(10);
  await page.clock.fastForward(185000);
  await expect(row('cancel-fresh')).toContainText('Cancellation unconfirmed');
  await expect(row('skip-fresh')).toContainText('Stop skip unconfirmed');
  await expect(row('prediction-fresh')).not.toContainText('Prediction');
  await expect(row('no-data')).toContainText('no realtime data');
});
